import GRDB
import LorvexDomain
import LorvexStore
import LorvexSync
import XCTest

@testable import LorvexCore

/// Ending a repeating task's series next to an occurrence generated by
/// completing the one before it: what the device writes, whether another
/// device accepts what it sends, and whether the result can be exported.
///
/// A generated occurrence names its predecessor. The link is valid only while
/// the predecessor records the occurrence as its next one in the same series,
/// so a write that takes either task out of the series has to drop the link
/// and end the predecessor's record.
final class TaskSeriesEndSyncTests: XCTestCase {

  private func makeService() throws -> SwiftLorvexCoreService {
    let schemaURL = URL(fileURLWithPath: #filePath)
      .deletingLastPathComponent()
      .deletingLastPathComponent()
      .deletingLastPathComponent()
      .deletingLastPathComponent()
      .deletingLastPathComponent()
      .appendingPathComponent("schema/schema.sql")
    let schemaSQL = try String(contentsOf: schemaURL, encoding: .utf8)
    let store = try LorvexStore.openInMemory(
      schemaSQL: schemaSQL, migrations: try SwiftLorvexCoreService.resolveSchemaMigrations())
    return SwiftLorvexCoreService(store: store)
  }

  /// The columns that place a task in a series.
  private struct Lineage: Equatable {
    var status: String
    var predecessor: String?
    var hasSeries: Bool
    var hasRule: Bool
    var rollover: String
    var successor: String?
  }

  private func lineage(_ service: SwiftLorvexCoreService, _ id: String) throws -> Lineage? {
    try service.read { db in
      try Row.fetchOne(
        db,
        sql: """
          SELECT status, spawned_from, recurrence_group_id IS NOT NULL,
                 recurrence IS NOT NULL, recurrence_rollover_state, recurrence_successor_id
          FROM tasks WHERE id = ?
          """,
        arguments: [id]
      ).map {
        Lineage(
          status: $0[0], predecessor: $0[1], hasSeries: $0[2], hasRule: $0[3],
          rollover: $0[4], successor: $0[5])
      }
    }
  }

  private func rejections(_ service: SwiftLorvexCoreService) throws -> [String] {
    try service.read { db in
      try String.fetchAll(
        db,
        sql: "SELECT message FROM error_logs WHERE source = 'sync.apply.inbound_invalid' ORDER BY id")
    }
  }

  /// Hand `receiver` everything `author` has queued, as one fetched page, and
  /// mark it sent. `reversed` hands the page over last record first, since
  /// records of different tasks arrive in no fixed order. Records of the
  /// entities in `holdingBack` stay queued on the author. Returns the
  /// receiver's log line for each record it refused as invalid.
  @discardableResult
  private func deliver(
    from author: SwiftLorvexCoreService, to receiver: SwiftLorvexCoreService,
    reversed: Bool = false, holdingBack: Set<String> = []
  ) throws -> [String] {
    let before = try rejections(receiver).count
    let pending = try author.pendingOutbound().filter {
      !holdingBack.contains($0.envelope.entityId)
    }
    let envelopes = pending.map(\.envelope)
    _ = try receiver.applyInbound(reversed ? envelopes.reversed() : envelopes, undecodable: 0)
    try author.markOutboundSynced(outboxIds: pending.map(\.outboxId))
    return Array(try rejections(receiver).dropFirst(before))
  }

  /// Records the device received and is holding back until another record
  /// arrives.
  private func heldBack(_ service: SwiftLorvexCoreService) throws -> Int {
    try service.read { db in
      try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM sync_pending_inbox") ?? 0
    }
  }

  /// Whether the device's task graph passes the check an export runs.
  private func canExport(_ service: SwiftLorvexCoreService) -> Bool {
    (try? service.read { db in
      try SwiftLorvexCoreService.nativeTaskGraphForDataExport(
        db, includeTaskCalendarEventLinkControlState: false)
    }) != nil
  }

  private func repairFailures(_ service: SwiftLorvexCoreService) throws -> [String] {
    try service.read { db in
      try String.fetchAll(
        db,
        sql: "SELECT message FROM error_logs WHERE source = 'sync.lineage_repair_failed' ORDER BY id")
    }
  }

  /// A daily task completed once on `author`, with both occurrences delivered
  /// to `receiver`. Returns the completed occurrence and the one it generated.
  private func completedOnceOnBothDevices(
    author: SwiftLorvexCoreService, receiver: SwiftLorvexCoreService
  ) async throws -> (first: String, second: String) {
    let first = try await author.createTask(
      .init(
        title: "Water the plants", priority: .p3, dueDate: Date(),
        recurrence: TaskRecurrenceRule(freq: .daily)))
    _ = try await author.completeTask(id: first.id)
    let second = try XCTUnwrap(
      try author.read { db in
        try String.fetchOne(
          db, sql: "SELECT id FROM tasks WHERE spawned_from = ?", arguments: [first.id])
      })
    XCTAssertEqual(try deliver(from: author, to: receiver), [])
    XCTAssertEqual(try lineage(receiver, second)?.predecessor, first.id)
    XCTAssertEqual(try lineage(receiver, first.id)?.successor, second)
    return (first.id, second)
  }

  private func assertSeriesEnded(
    first: String, second: String,
    author: SwiftLorvexCoreService, receiver: SwiftLorvexCoreService,
    file: StaticString = #filePath, line: UInt = #line
  ) throws {
    let endedOccurrence = Lineage(
      status: "cancelled", predecessor: nil, hasSeries: false, hasRule: false,
      rollover: "ended", successor: nil)
    XCTAssertEqual(try lineage(author, second), endedOccurrence, file: file, line: line)
    XCTAssertEqual(try lineage(receiver, second), endedOccurrence, file: file, line: line)

    // The completed occurrence keeps its rule and series as history and no
    // longer names a next occurrence.
    let finishedOccurrence = Lineage(
      status: "completed", predecessor: nil, hasSeries: true, hasRule: true,
      rollover: "ended", successor: nil)
    XCTAssertEqual(try lineage(author, first), finishedOccurrence, file: file, line: line)
    XCTAssertEqual(try lineage(receiver, first), finishedOccurrence, file: file, line: line)
  }

  func testCancellingTheSeriesOnAGeneratedOccurrenceIsAcceptedByAPeer() async throws {
    let author = try makeService()
    let receiver = try makeService()
    let (first, second) = try await completedOnceOnBothDevices(author: author, receiver: receiver)

    let result = try await author.batchCancelTasks(ids: [second], cancelSeries: true)
    XCTAssertEqual(result.cancelled.map(\.id), [second])

    XCTAssertEqual(try deliver(from: author, to: receiver), [])
    try assertSeriesEnded(first: first, second: second, author: author, receiver: receiver)
  }

  func testCancellingAListWithItsSeriesIsAcceptedByAPeer() async throws {
    let author = try makeService()
    let receiver = try makeService()
    let (first, second) = try await completedOnceOnBothDevices(author: author, receiver: receiver)
    let listID = try XCTUnwrap(
      try author.read { db in
        try String.fetchOne(db, sql: "SELECT list_id FROM tasks WHERE id = ?", arguments: [second])
      })

    let cancelled = try await author.batchCancelTasksInList(
      listID: listID, statuses: nil, cancelSeries: true)
    XCTAssertEqual(cancelled.map(\.id), [second])

    XCTAssertEqual(try deliver(from: author, to: receiver), [])
    try assertSeriesEnded(first: first, second: second, author: author, receiver: receiver)
  }

  /// A device can hold a generated occurrence that kept its predecessor after
  /// losing its series. The peer refuses that record; local maintenance turns
  /// the task into an ordinary one-off and sends it again, with the
  /// predecessor that still named it.
  func testMaintenanceRepairsAnOccurrenceThatKeptItsPredecessorWithoutASeries() async throws {
    for reversed in [false, true] {
      let author = try makeService()
      let receiver = try makeService()
      let (first, second) = try await completedOnceOnBothDevices(
        author: author, receiver: receiver)

      try author.withWrite { db, hlc, deviceId in
        try db.execute(
          sql: Self.loseTheSeriesAndKeepThePredecessor,
          arguments: [hlc.nextVersionString(), second])
        try author.enqueueUpsert(db, hlc: hlc, deviceId: deviceId, kind: .task, entityId: second)
      }
      let context = "reversed delivery: \(reversed)"
      XCTAssertEqual(
        try deliver(from: author, to: receiver).count, 1,
        "the peer refuses an occurrence that names a predecessor without a series")
      XCTAssertEqual(try lineage(receiver, second)?.status, "open", context)

      try author.runLocalRetentionMaintenance(includeActiveOutboxCap: false)

      XCTAssertEqual(
        Set(try author.pendingOutbound().map(\.envelope.entityId)), [first, second],
        "the repaired occurrence and its predecessor are both queued")
      XCTAssertEqual(try deliver(from: author, to: receiver, reversed: reversed), [], context)
      XCTAssertEqual(try deliver(from: receiver, to: author), [], context)
      try assertSeriesEnded(first: first, second: second, author: author, receiver: receiver)
      XCTAssertEqual(try repairFailures(author), [], context)

      try author.runLocalRetentionMaintenance(includeActiveOutboxCap: false)
      XCTAssertTrue(
        try author.pendingOutbound().isEmpty, "a second pass finds nothing to repair")
    }
  }

  /// The earlier occurrence still repeats after the later one left the series,
  /// so reopening and completing it generates the later one again under the
  /// same id. The peer holds that task without a series when the earlier
  /// occurrence's record arrives.
  func testCompletingTheEarlierOccurrenceAgainAfterTheSeriesEndedIsAcceptedByAPeer() async throws {
    for endsByCancel in [true, false] {
      for reversed in [false, true] {
        let author = try makeService()
        let receiver = try makeService()
        let (first, second) = try await completedOnceOnBothDevices(
          author: author, receiver: receiver)
        if endsByCancel {
          _ = try await author.batchCancelTasks(ids: [second], cancelSeries: true)
        } else {
          _ = try await author.removeTaskRecurrence(taskID: second)
        }
        XCTAssertEqual(try deliver(from: author, to: receiver), [])

        _ = try await author.reopenTask(id: first)
        _ = try await author.completeTask(id: first)

        let context = "ended by cancel: \(endsByCancel), reversed delivery: \(reversed)"
        XCTAssertEqual(try deliver(from: author, to: receiver, reversed: reversed), [], context)
        XCTAssertEqual(try heldBack(receiver), 0, context)
        let earlier = Lineage(
          status: "completed", predecessor: nil, hasSeries: true, hasRule: true,
          rollover: "authorized", successor: second)
        let later = Lineage(
          status: "open", predecessor: first, hasSeries: true, hasRule: true,
          rollover: "none", successor: nil)
        XCTAssertEqual(try lineage(author, first), earlier, context)
        XCTAssertEqual(try lineage(receiver, first), earlier, context)
        XCTAssertEqual(try lineage(author, second), later, context)
        XCTAssertEqual(try lineage(receiver, second), later, context)
        XCTAssertTrue(canExport(receiver), context)
      }
    }
  }

  /// Reopening a completed occurrence cancels the one it generated and keeps
  /// it linked, for a later completion to revive. Taking the reopened task out
  /// of the series ends that arrangement, so the cancelled occurrence stands
  /// alone.
  func testEndingTheSeriesOfAReopenedOccurrenceLeavesAnExportableGraph() async throws {
    for endsByCancel in [true, false] {
      for reversed in [false, true] {
        let author = try makeService()
        let receiver = try makeService()
        let (first, second) = try await completedOnceOnBothDevices(
          author: author, receiver: receiver)
        _ = try await author.reopenTask(id: first)
        if endsByCancel {
          _ = try await author.batchCancelTasks(ids: [first], cancelSeries: true)
        } else {
          _ = try await author.removeTaskRecurrence(taskID: first)
        }

        let context = "ended by cancel: \(endsByCancel), reversed delivery: \(reversed)"
        XCTAssertEqual(try deliver(from: author, to: receiver, reversed: reversed), [], context)
        XCTAssertEqual(try deliver(from: receiver, to: author), [], context)
        let leftBehind = Lineage(
          status: "cancelled", predecessor: nil, hasSeries: true, hasRule: true,
          rollover: "ended", successor: nil)
        for device in [author, receiver] {
          XCTAssertEqual(try lineage(device, second), leftBehind, context)
          XCTAssertEqual(try lineage(device, first)?.hasSeries, false, context)
          XCTAssertTrue(canExport(device), context)
        }
      }
    }
  }

  /// Records of different tasks arrive in no fixed order. When the earlier
  /// occurrence's record arrives first, it says only that the earlier
  /// occurrence has no next one; what became of the later occurrence is in
  /// that task's own record.
  func testEndingTheSeriesOnTheLaterOccurrenceConvergesInEitherDeliveryOrder() async throws {
    for endsByCancel in [true, false] {
      for reversed in [false, true] {
        let author = try makeService()
        let receiver = try makeService()
        let (first, second) = try await completedOnceOnBothDevices(
          author: author, receiver: receiver)
        if endsByCancel {
          _ = try await author.batchCancelTasks(ids: [second], cancelSeries: true)
        } else {
          _ = try await author.removeTaskRecurrence(taskID: second)
        }

        let context = "ended by cancel: \(endsByCancel), reversed delivery: \(reversed)"
        XCTAssertEqual(try deliver(from: author, to: receiver, reversed: reversed), [], context)
        // Whatever the receiver worked out for itself goes back to the author.
        XCTAssertEqual(try deliver(from: receiver, to: author), [], context)

        // Turning the repeat off keeps the task; cancelling the series
        // cancels it.
        let later = Lineage(
          status: endsByCancel ? "cancelled" : "open", predecessor: nil, hasSeries: false,
          hasRule: false, rollover: endsByCancel ? "ended" : "none", successor: nil)
        let earlier = Lineage(
          status: "completed", predecessor: nil, hasSeries: true, hasRule: true,
          rollover: "ended", successor: nil)
        for device in [author, receiver] {
          XCTAssertEqual(try lineage(device, second), later, context)
          XCTAssertEqual(try lineage(device, first), earlier, context)
          XCTAssertTrue(canExport(device), context)
        }
        XCTAssertEqual(try heldBack(receiver), 0, context)
      }
    }
  }

  /// One device completes a repeating task, which generates the next
  /// occurrence. Another device, which has not seen that, marks the same task
  /// in progress afterwards. The later status wins, so the task is not
  /// completed, and the generated occurrence must not stay open beside it.
  func testACompletionOverriddenOnAnotherDeviceStillCancelsTheGeneratedOccurrence()
    async throws
  {
    for reversed in [false, true] {
      let completer = try makeService()
      let starter = try makeService()
      let first = try await completer.createTask(
        .init(
          title: "Water the plants", priority: .p3, dueDate: Date(),
          recurrence: TaskRecurrenceRule(freq: .daily)))
      XCTAssertEqual(try deliver(from: completer, to: starter), [])

      _ = try await completer.completeTask(id: first.id)
      let second = try XCTUnwrap(
        try completer.read { db in
          try String.fetchOne(
            db, sql: "SELECT id FROM tasks WHERE spawned_from = ?", arguments: [first.id])
        })
      // The other device's change has to carry the later stamp.
      try await Task.sleep(for: .milliseconds(5))
      _ = try await starter.startTaskReturningTask(id: first.id)

      let context = "reversed delivery: \(reversed)"
      XCTAssertEqual(try deliver(from: completer, to: starter, reversed: reversed), [], context)
      XCTAssertEqual(try deliver(from: starter, to: completer), [], context)
      XCTAssertEqual(try deliver(from: completer, to: starter), [], context)
      for device in [completer, starter] {
        XCTAssertEqual(try lineage(device, first.id)?.status, "in_progress", context)
        XCTAssertEqual(try lineage(device, second)?.status, "cancelled", context)
        XCTAssertEqual(try heldBack(device), 0, context)
      }
    }
  }

  /// A device holds the completed occurrence without the one it generated,
  /// whose record has not reached it. There the completion is undone, the
  /// repeat is changed to end, and the task is completed again, this time
  /// generating nothing. No device ever writes a cancel for the generated
  /// occurrence, so each device has to work it out from the earlier
  /// occurrence's record.
  func testCompletingAgainWithoutANextOccurrenceCancelsTheOneAnotherDeviceGenerated()
    async throws
  {
    let generator = try makeService()
    let other = try makeService()
    let first = try await generator.createTask(
      .init(
        title: "Water the plants", priority: .p3, dueDate: Date(),
        recurrence: TaskRecurrenceRule(freq: .daily)))
    XCTAssertEqual(try deliver(from: generator, to: other), [])

    _ = try await generator.completeTask(id: first.id)
    let second = try XCTUnwrap(
      try generator.read { db in
        try String.fetchOne(
          db, sql: "SELECT id FROM tasks WHERE spawned_from = ?", arguments: [first.id])
      })
    XCTAssertEqual(try deliver(from: generator, to: other, holdingBack: [second]), [])
    XCTAssertNil(try lineage(other, second))
    XCTAssertEqual(try lineage(other, first.id)?.rollover, "authorized")

    try await Task.sleep(for: .milliseconds(5))
    _ = try await other.reopenTask(id: first.id)
    _ = try await other.setTaskRecurrence(
      taskID: first.id, rule: TaskRecurrenceRule(freq: .daily, count: 1))
    _ = try await other.completeTask(id: first.id)
    XCTAssertEqual(try lineage(other, first.id)?.rollover, "ended")

    XCTAssertEqual(try deliver(from: other, to: generator), [])
    XCTAssertEqual(try deliver(from: generator, to: other), [])
    XCTAssertEqual(try deliver(from: other, to: generator), [])
    for device in [generator, other] {
      XCTAssertEqual(try lineage(device, first.id)?.status, "completed")
      XCTAssertEqual(try lineage(device, first.id)?.rollover, "ended")
      XCTAssertEqual(try lineage(device, second)?.status, "cancelled")
      XCTAssertEqual(try heldBack(device), 0)
    }
  }

  /// One device turns the repeat off on a generated occurrence. Another, which
  /// has not seen that, moves the same task's due date afterwards. The two
  /// edits share the schedule fields, so the later one decides them on both
  /// devices; the earlier occurrence still stops recording the task, and the
  /// task must end up standing alone.
  func testALaterScheduleEditOnAnotherDeviceAfterTheRepeatIsTurnedOffConverges() async throws {
    for reversed in [false, true] {
      let author = try makeService()
      let receiver = try makeService()
      let (first, second) = try await completedOnceOnBothDevices(
        author: author, receiver: receiver)

      _ = try await author.removeTaskRecurrence(taskID: second)
      try await Task.sleep(for: .milliseconds(5))
      _ = try await receiver.updateTask(
        TaskUpdateDraft(id: second, dueDate: .set(Date().addingTimeInterval(5 * 86_400))))

      let context = "reversed delivery: \(reversed)"
      XCTAssertEqual(try deliver(from: author, to: receiver, reversed: reversed), [], context)
      XCTAssertEqual(try deliver(from: receiver, to: author), [], context)
      XCTAssertEqual(try deliver(from: author, to: receiver), [], context)
      XCTAssertEqual(try deliver(from: receiver, to: author), [], context)

      let later = try XCTUnwrap(try lineage(author, second), context)
      XCTAssertEqual(try lineage(receiver, second), later, context)
      XCTAssertNil(later.predecessor, context)
      XCTAssertEqual(later.status, "open", context)
      XCTAssertEqual(try lineage(receiver, first), try lineage(author, first), context)
      XCTAssertNil(try lineage(author, first)?.successor, context)
      for device in [author, receiver] {
        XCTAssertTrue(canExport(device), context)
        XCTAssertEqual(try heldBack(device), 0, context)
        XCTAssertTrue(try device.pendingOutbound().isEmpty, context)
      }
    }
  }

  /// Leaves a generated occurrence cancelled and outside its series while it
  /// still names its predecessor: the state the repair exists for.
  private static let loseTheSeriesAndKeepThePredecessor = """
    UPDATE tasks SET status = 'cancelled', recurrence = NULL,
      recurrence_group_id = NULL, canonical_occurrence_date = NULL,
      recurrence_instance_key = NULL, recurrence_rollover_state = 'ended',
      recurrence_successor_id = NULL,
      schedule_version = ?1, lifecycle_version = ?1, version = ?1
    WHERE id = ?2
    """

  /// Two generated occurrences on `author` that both need the repair, each
  /// with the occurrence it came from.
  private func twoOccurrencesNeedingRepair(
    author: SwiftLorvexCoreService, receiver: SwiftLorvexCoreService
  ) async throws -> (blocked: (first: String, second: String), repairable: String) {
    let blocked = try await completedOnceOnBothDevices(author: author, receiver: receiver)
    let (_, repairable) = try await completedOnceOnBothDevices(author: author, receiver: receiver)
    try author.withWrite { db, hlc, _ in
      for id in [blocked.second, repairable] {
        try db.execute(
          sql: Self.loseTheSeriesAndKeepThePredecessor,
          arguments: [hlc.nextVersionString(), id])
      }
    }
    return (blocked, repairable)
  }

  /// One task the repair cannot change must not hold back another, and is
  /// reported in the diagnostics log once, not on every pass. The task is
  /// left exactly as it was, whether the failure is in writing it or in
  /// queuing it for the other devices.
  func testATaskTheRepairCannotChangeIsLoggedOnceAndDoesNotHoldBackOthers() async throws {
    for refusesQueuing in [false, true] {
      let author = try makeService()
      let receiver = try makeService()
      let (blocked, repairable) = try await twoOccurrencesNeedingRepair(
        author: author, receiver: receiver)
      try author.write { db in
        if refusesQueuing {
          // The task and its predecessor are queued in id order. Refusing
          // the later one means the earlier is already queued and has to be
          // taken back.
          try db.execute(
            sql: """
              CREATE TEMP TRIGGER refuse_one_record BEFORE INSERT ON sync_outbox
              WHEN NEW.entity_id = '\(max(blocked.first, blocked.second))'
              BEGIN SELECT RAISE(ABORT, 'refused for the test'); END
              """)
        } else {
          try db.execute(
            sql: """
              CREATE TEMP TRIGGER refuse_one_task BEFORE UPDATE ON tasks
              WHEN OLD.id = '\(blocked.second)' AND NEW.spawned_from IS NULL
              BEGIN SELECT RAISE(ABORT, 'refused for the test'); END
              """)
        }
      }
      let context = "refuses queuing: \(refusesQueuing)"

      try author.runLocalRetentionMaintenance(includeActiveOutboxCap: false)

      XCTAssertNil(try lineage(author, repairable)?.predecessor, context)
      XCTAssertEqual(try lineage(author, blocked.second)?.predecessor, blocked.first, context)
      XCTAssertEqual(
        try lineage(author, blocked.first)?.successor, blocked.second,
        "the predecessor of a task that was not repaired keeps its record")
      let queued = Set(try author.pendingOutbound().map(\.envelope.entityId))
      XCTAssertTrue(queued.isDisjoint(with: [blocked.first, blocked.second]), context)
      XCTAssertEqual(try repairFailures(author).count, 1, context)
      XCTAssertEqual(try deliver(from: author, to: receiver), [], context)

      try author.runLocalRetentionMaintenance(includeActiveOutboxCap: false)
      XCTAssertEqual(try repairFailures(author).count, 1, "the failure is logged once")
      XCTAssertTrue(try author.pendingOutbound().isEmpty, context)
    }
  }

  /// A task stamped at the top of the clock's range cannot be overtaken by
  /// replaying the pass on a later stamp. It fails the pass it is found in
  /// and is left out afterwards, so the next pass repairs the others.
  func testATaskStampedBeyondAnyReplayIsLeftOutSoTheOthersAreRepaired() async throws {
    let author = try makeService()
    let receiver = try makeService()
    let (blocked, repairable) = try await twoOccurrencesNeedingRepair(
      author: author, receiver: receiver)
    try author.write { db in
      try db.execute(
        sql: """
          UPDATE tasks SET
            schedule_version = '9999913599999_9999_' || substr(schedule_version, 20),
            version = '9999913599999_9999_' || substr(version, 20)
          WHERE id = ?
          """,
        arguments: [blocked.second])
    }

    XCTAssertThrowsError(
      try author.runLocalRetentionMaintenance(includeActiveOutboxCap: false))
    XCTAssertNotNil(try lineage(author, repairable)?.predecessor)
    XCTAssertEqual(try repairFailures(author).count, 1)

    try author.runLocalRetentionMaintenance(includeActiveOutboxCap: false)
    XCTAssertNil(try lineage(author, repairable)?.predecessor)
    XCTAssertEqual(try lineage(author, blocked.second)?.predecessor, blocked.first)
    XCTAssertEqual(try repairFailures(author).count, 1, "the task is logged once")
    XCTAssertEqual(try deliver(from: author, to: receiver), [])
  }

  /// A repair pass that cannot commit changes nothing and is tried again on
  /// the next pass; the diagnostics log reports it once.
  func testARepairPassThatCannotCommitIsLoggedOnceAndTriedAgain() async throws {
    let author = try makeService()
    let receiver = try makeService()
    let (blocked, repairable) = try await twoOccurrencesNeedingRepair(
      author: author, receiver: receiver)
    // Every write transaction of the service ends by advancing this counter.
    try author.write { db in
      try db.execute(
        sql: """
          CREATE TEMP TRIGGER refuse_commit BEFORE INSERT ON local_counters
          BEGIN SELECT RAISE(ABORT, 'refused for the test'); END
          """)
    }

    for _ in 0..<2 {
      XCTAssertThrowsError(
        try author.runLocalRetentionMaintenance(includeActiveOutboxCap: false))
      XCTAssertNotNil(try lineage(author, repairable)?.predecessor)
      XCTAssertNotNil(try lineage(author, blocked.second)?.predecessor)
      XCTAssertTrue(try author.pendingOutbound().isEmpty)
    }
    XCTAssertEqual(try repairFailures(author).count, 1, "the failed pass is logged once")

    try author.write { db in try db.execute(sql: "DROP TRIGGER refuse_commit") }
    try author.runLocalRetentionMaintenance(includeActiveOutboxCap: false)
    XCTAssertNil(try lineage(author, repairable)?.predecessor)
    XCTAssertNil(try lineage(author, blocked.second)?.predecessor)
    XCTAssertEqual(try deliver(from: author, to: receiver), [])
  }
}
